// Writes the translations of the hand-written pages as pages of their own, so search
// engines see them in every language:
//   /  ->  /en/, /de/, /it/, /es/
//   /magnitni-buri/  ->  /en/magnitni-buri/, /de/magnitni-buri/ ...
//   /weather/, /maps/, /holliday_calendar/  ->  /en/weather/, /de/maps/ ...
// The Bulgarian pages stay written by hand and are the templates. The texts are the ones the
// pages already use in the browser:
//   home:    homepageTranslations in /index.html
//   storms:  PAGE and T in /js/storm-page.js
//   menu:    navTexts in /js/mobile-nav.js
// Home and storms are translated completely in the HTML. The forecast, maps and holiday pages
// get their own address, title, description, heading and menu (text-main.js and the
// dictionaries of their scripts); the rest of the page is translated by its scripts when it
// opens, as before.
// Run after changing any of these pages or texts:
//   node .github/scripts/build-main.js [--sitemap]
const fs = require('fs');
const path = require('path');
const vm = require('vm');
const I18N = require('./i18n.js');
const APP_TEXT = require('./text-main.js');

const ROOT = process.cwd();
const SITE = 'https://weatherpulse.eu';
const TARGETS = I18N.LANGS.filter(lang => lang !== 'bg');
// Pages this script writes; links to them (and to every page that already has a translation) follow the language
const OWN = ['/', '/magnitni-buri/', '/weather/', '/maps/', '/holliday_calendar/'];

const read = file => fs.readFileSync(path.join(ROOT, file), 'utf8').replace(/\r\n/g, '\n');
const esc = I18N.esc;

// The source of "const <name> = { ... };" in a script (closed at the same indentation)
function declaration(source, name, file) {
  const match = source.match(new RegExp(`^([ \\t]*)const ${name} = \\{[\\s\\S]*?^\\1\\};`, 'm'));
  if (!match) throw new Error(`${file}: "const ${name} = {" not found`);
  return match[0];
}
const evaluate = (code, names) => vm.runInNewContext(`${code}\n({ ${names.join(', ')} })`);

// Replace exactly once, or stop: a template that changed must not give a half-translated page
function once(html, pattern, replacement, what) {
  let count = 0;
  const result = html.replace(pattern, (...args) => { count++; return typeof replacement === 'function' ? replacement(...args) : replacement; });
  if (count !== 1) throw new Error(`${what}: expected 1 match, found ${count}`);
  return result;
}

// Text of the element with this attribute value (elements with plain text inside)
const setText = (html, attribute, value, text, what) =>
  once(html, new RegExp(`(<(\\w+)\\b[^>]*\\b${attribute}="${value}"[^>]*>)[\\s\\S]*?(</\\2>)`), (m, open, tag, close) => open + esc(text) + close, what);

// ---- What every translated page needs ----
// pending: the body is still Bulgarian in the HTML and is translated by the page's scripts
// (hidden until then: html.i18n-pending, removed by /js/mobile-nav.js)
function common(html, lang, url, { title, ogTitle, description, source, pending = false }) {
  const pageUrl = `/${lang}${url}`;
  html = once(html, '<html lang="bg">', `<html lang="${lang}" data-page-lang="${lang}">`, 'html tag');
  html = once(html, '<head>\n', `<head>\n  <!-- Generated by .github/scripts/build-main.js from ${source}; edit that page or its texts, not this file -->\n`, 'head');
  html = once(html, /<title>[^<]*<\/title>/, `<title>${esc(title)}</title>`, 'title');
  html = once(html, /<link rel="canonical" href="[^"]*" \/>/, `<link rel="canonical" href="${SITE}${pageUrl}" />`, 'canonical');
  html = once(html, /<meta name="description" content="[^"]*">/, `<meta name="description" content="${esc(description)}">`, 'description');
  html = once(html, /<meta property="og:locale" content="[^"]*">/, `<meta property="og:locale" content="${I18N.OG_LOCALE[lang]}">`, 'og:locale');
  html = once(html, /<meta property="og:title" content="[^"]*">/, `<meta property="og:title" content="${esc(ogTitle)}">`, 'og:title');
  html = once(html, /<meta property="og:description" content="[^"]*">/, `<meta property="og:description" content="${esc(description)}">`, 'og:description');
  html = once(html, /<meta property="og:url" content="[^"]*">/, `<meta property="og:url" content="${SITE}${pageUrl}">`, 'og:url');
  // The Bulgarian page sends visitors to their language; a translation remembers its own
  html = once(html, /  <script>\n    \(function\(\) \{\n      \/\/ Bulgarian original\.[\s\S]*?<\/script>/, `  <script>
    (function() {
      // Translated page: the language of the page is the language of the site from now on
      try { localStorage.setItem('selectedLanguage', '${lang}'); } catch (e) { /* storage blocked */ }${pending ? `
      // Hidden until the scripts have translated the Bulgarian HTML (no flash of Bulgarian text)
      document.documentElement.classList.add('i18n-pending');` : ''}
    })();
  </script>`, 'language script');

  // Menu and other links marked with data-nav
  html = html.replace(/(<(\w+)\b[^>]*\bdata-nav="(\w+)"[^>]*>)[^<]*(<\/\2>)/g, (m, open, tag, key, close) => {
    if (!NAV[key] || !NAV[key][lang]) throw new Error(`mobile-nav.js: no "${key}" text in ${lang}`);
    return open + esc(NAV[key][lang]) + close;
  });
  // Links to pages that exist in this language
  html = html.replace(/href="(\/[^"?#]*\/|\/)([?#][^"]*)?"/g, (m, page, rest = '') => {
    const translated = OWN.includes(page) || fs.existsSync(path.join(ROOT, lang, page, 'index.html'));
    return translated ? `href="/${lang}${page}${rest}"` : m;
  });
  html = html.replace(/alt="Лого"/g, `alt="${I18N.LOGO_ALT[lang]}"`);
  return html;
}

// Cyrillic left in the visible page (outside scripts and comments) means a text was missed
function leftovers(html, file) {
  const visible = html.replace(/<script[\s\S]*?<\/script>/g, '').replace(/<!--[\s\S]*?-->/g, '');
  const lines = visible.split('\n').filter(line => /[Ѐ-ӿ]/.test(line));
  if (lines.length) throw new Error(`${file}: Bulgarian text left in the page:\n  ${lines.map(line => line.trim().slice(0, 120)).join('\n  ')}`);
}

function write(url, lang, html, complete = true) {
  const file = path.join(lang, url, 'index.html');
  if (complete) leftovers(html, file);
  fs.mkdirSync(path.dirname(path.join(ROOT, file)), { recursive: true });
  fs.writeFileSync(path.join(ROOT, file), html);
}

const NAV = evaluate(declaration(read('js/mobile-nav.js'), 'navTexts', 'js/mobile-nav.js'), ['navTexts']).navTexts;

// ---- Home ----
function home() {
  const template = read('index.html');
  const texts = evaluate(
    ['homepageTranslations', 'elements', 'titles'].map(name => declaration(template, name, 'index.html')).join('\n'),
    ['homepageTranslations', 'elements', 'titles']);

  TARGETS.forEach(lang => {
    const T = texts.homepageTranslations[lang];
    if (!T || !T.metaDescription) throw new Error(`index.html: homepageTranslations.${lang}.metaDescription is missing`);
    const title = `${T.heroTitle} | Weather Pulse`;
    let html = common(template, lang, '/', { title, ogTitle: title, description: T.metaDescription, source: '/index.html' });

    // the same elements updateHomepageContent() fills in the browser
    Object.entries(texts.elements).forEach(([id, key]) => {
      if (T[key] && html.includes(`id="${id}"`)) html = setText(html, 'id', id, T[key], `#${id}`);
    });
    Object.entries(texts.titles).forEach(([selector, key]) => {
      const attribute = selector[0] === '#' ? `id="${selector.slice(1)}"` : `class="${selector.slice(1)}"`;
      html = once(html, new RegExp(`(<\\w+\\b[^>]*\\b${attribute}[^>]*\\btitle=")[^"]*"|(<\\w+\\b[^>]*\\btitle=")[^"]*("[^>]*\\b${attribute})`),
        (m, before, before2, after) => (before ? `${before}${esc(T[key])}"` : `${before2}${esc(T[key])}${after}`), selector);
    });
    // Bulgarian cities: Latin names and the translated city pages
    html = html.replace(/href="vremeto\/([a-z-]+)\/"([^>]*)>[^<]*</g, (m, slug, attributes) => `href="/${lang}/vremeto/${slug}/"${attributes}>${esc(I18N.latinName(lang, slug))}<`);
    html = once(html, /<script type="application\/ld\+json">[^<]*<\/script>/,
      `<script type="application/ld+json">${JSON.stringify({
        '@context': 'https://schema.org',
        '@graph': [
          { '@type': 'WebSite', '@id': `${SITE}/#website`, name: 'Weather Pulse', url: `${SITE}/${lang}/`, inLanguage: lang, publisher: { '@id': `${SITE}/#organization` } },
          { '@type': 'Organization', '@id': `${SITE}/#organization`, name: 'Weather Pulse', url: `${SITE}/`, logo: `${SITE}/images/icons/icon-512.png` }
        ]
      })}</script>`, 'JSON-LD');
    write('/', lang, html);
  });
}

// ---- Magnetic storms ----
// The forecast table written every morning by build-storms.js (between two comment marks in
// #stormForecast) is in the language of each page: the Bulgarian one is taken out of the
// template and every translation keeps its own
const KP_BLOCK = /<div class="kp-forecast" id="stormForecast">(<!-- kp-forecast:start -->[\s\S]*?<!-- kp-forecast:end -->)<\/div>/;
const KP_EMPTY = '<div class="kp-forecast" id="stormForecast" hidden></div>';

function storms() {
  const template = read('magnitni-buri/index.html').replace(KP_BLOCK, KP_EMPTY);
  const script = read('js/storm-page.js');
  const { PAGE, T } = evaluate(`${declaration(script, 'PAGE', 'js/storm-page.js')}\n${declaration(script, 'T', 'js/storm-page.js')}`, ['PAGE', 'T']);
  const text = (group, key, lang) => {
    if (!group[key] || !group[key][lang]) throw new Error(`js/storm-page.js: no "${key}" text in ${lang}`);
    return group[key][lang];
  };

  TARGETS.forEach(lang => {
    const title = text(PAGE, 'title', lang);
    let html = common(template, lang, '/magnitni-buri/', {
      title, ogTitle: title.replace(/ \| Weather Pulse$/, ''), description: text(PAGE, 'description', lang), source: '/magnitni-buri/index.html'
    });
    html = html.replace(/(<(\w+)\b[^>]*\bdata-i18n="(\w+)"[^>]*>)[\s\S]*?(<\/\2>)/g, (m, open, tag, key, close) => open + esc(text(PAGE, key, lang)) + close);
    // texts the script writes when it runs
    html = setText(html, 'id', 'stormAlertsButton', text(T, 'alertsOn', lang), 'alerts button');
    html = setText(html, 'id', 'copyWidgetCode', text(T, 'copy', lang), 'copy button');
    const widgetName = esc(text(T, 'widgetName', lang));
    html = once(html, /(<textarea id="widgetCode"[^>]*>)[^<]*(<\/textarea>)/, (m, open, close) =>
      `${open}&lt;iframe src="${SITE}/widget/kp.html?lang=${lang}" width="320" height="190" style="border:0" title="${widgetName}" loading="lazy"&gt;&lt;/iframe&gt;${close}`, 'widget code');
    html = once(html, /(<iframe id="widgetPreview" src=")[^"]*("[^>]* title=")[^"]*"/, (m, a, b) => `${a}/widget/kp.html?lang=${lang}${b}${widgetName}"`, 'widget preview');
    // The questions and answers of the page as FAQ data
    const faq = {
      '@context': 'https://schema.org',
      '@type': 'FAQPage',
      inLanguage: lang,
      mainEntity: [1, 2, 3, 4, 5].map(n => ({
        '@type': 'Question',
        name: text(PAGE, `q${n}`, lang),
        acceptedAnswer: { '@type': 'Answer', text: text(PAGE, `a${n}`, lang).replace(/:$/, '.') }
      }))
    };
    html = once(html, /<script type="application\/ld\+json">[\s\S]*?<\/script>/, `<script type="application/ld+json">\n${JSON.stringify(faq, null, 2)}\n  </script>`, 'JSON-LD');
    const file = path.join(ROOT, lang, 'magnitni-buri', 'index.html');
    const written = fs.existsSync(file) ? read(path.join(lang, 'magnitni-buri', 'index.html')).match(KP_BLOCK) : null;
    if (written) html = once(html, KP_EMPTY, written[0], 'forecast block');
    write('/magnitni-buri/', lang, html);
  });
}

// ---- Forecast, maps, holiday calendar ----
function apps() {
  // the headings the scripts of the pages put there
  const dictionary = (file, key) => {
    const { translations } = evaluate(declaration(read(file), 'translations', file), ['translations']);
    return lang => {
      if (!translations[lang] || !translations[lang][key]) throw new Error(`${file}: no "${key}" text in ${lang}`);
      return translations[lang][key];
    };
  };
  const HEADING = {
    '/weather/': dictionary('weather/language-switcher.js', 'title'),
    '/maps/': dictionary('maps/js/language-switcher.js', 'mapsTitle'),
    '/holliday_calendar/': dictionary('language-switcher.js', 'holidayCalendarTitle')
  };
  Object.keys(HEADING).forEach(url => {
    const template = read(`${url.slice(1)}index.html`);
    TARGETS.forEach(lang => {
      const T = APP_TEXT[url][lang];
      if (!T || !T.title || !T.description) throw new Error(`text-main.js: no texts for ${url} in ${lang}`);
      const title = `${T.title} | Weather Pulse`;
      let html = common(template, lang, url, { title, ogTitle: title, description: T.description, source: `${url}index.html`, pending: true });
      html = once(html, /(<h1\b[^>]*>)[^<]*(<\/h1>)/, (m, open, close) => open + esc(HEADING[url](lang)) + close, 'h1');
      write(url, lang, html, false);
    });
  });
}

home();
storms();
apps();
console.log(`Wrote /, /magnitni-buri/, /weather/, /maps/ and /holliday_calendar/ in ${TARGETS.join(', ')}.`);

if (process.argv.includes('--sitemap')) {
  const today = new Date().toISOString().slice(0, 10);
  const file = path.join(ROOT, 'sitemap.xml');
  const sitemap = fs.readFileSync(file, 'utf8');
  const nl = sitemap.includes('\r\n') ? '\r\n' : '\n';
  const urls = OWN.flatMap(url => TARGETS.map(lang => `/${lang}${url}`));
  const missing = urls.filter(url => !sitemap.includes(`${SITE}${url}<`));
  const entries = missing.map(url => ['  <url>', `    <loc>${SITE}${url}</loc>`, `    <lastmod>${today}</lastmod>`, '    <priority>0.8</priority>', '  </url>', ''].join(nl)).join(nl);
  fs.writeFileSync(file, sitemap.replace('</urlset>', entries + '</urlset>'));
  console.log(`Added ${missing.length} URLs to sitemap.xml.`);
}
